:root { color-scheme: light dark; --page: #eef0f2; --card: #ffffff; --ink: #1c2126; --muted: #6c7780; --edge: #e9ebed; --pill: #f2f4f5; --code: #f6f7f8; --cta: #16191c; --cta-ink: #ffffff; --shadow: 0 1px 4px rgb(0 0 0 / 0.07); }@media (prefers-color-scheme: dark) {
  :root { --page: #0f1214; --card: #1a1f23; --ink: #edf0f2; --muted: #97a2aa; --edge: #2e363c; --pill: #262d33; --code: #14181b; --cta: #edf0f2; --cta-ink: #16191c; --shadow: 0 1px 4px rgb(0 0 0 / 0.4); }
}* { box-sizing: border-box; }body { background: var(--page); color: var(--ink); display: grid; font-family: system-ui, sans-serif; margin: 0px; min-height: 100vh; padding: 24px; place-items: center; }:focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; }.app { background: var(--card); border: 1px solid var(--edge); border-radius: 16px; box-shadow: var(--shadow); display: flex; flex-direction: column; gap: 16px; height: min(700px, -48px + 100vh); padding: 18px; width: min(1040px, 100%); }.toolbar { display: flex; gap: 8px; }.pill { align-items: center; background: var(--pill); border: 0px; border-radius: 9px; color: inherit; display: inline-flex; font-family: inherit; font-size: 0.8125rem; font-weight: 550; gap: 6px; padding: 8px 14px; }button.pill { cursor: pointer; }button.pill:hover { background: color-mix(in srgb, var(--pill) 84%, var(--ink)); }.pill svg { height: 14px; width: 14px; }.picker { padding: 0px; position: relative; }.picker svg { color: var(--muted); pointer-events: none; position: absolute; right: 11px; top: 50%; transform: translateY(-50%); }.picker select { appearance: none; background: none; border: 0px; border-radius: 9px; color: inherit; cursor: pointer; font-family: inherit; font-size: 0.8125rem; font-weight: 550; padding: 8px 32px 8px 14px; }.columns { display: flex; flex: 1 1 0%; gap: 8px; list-style: none; margin: 0px; min-height: 0px; padding: 0px; }.column { align-items: flex-end; border-radius: 10px; display: flex; flex: 1 1 0%; min-width: 0px; padding: 14px; }.hex { display: flex; flex-direction: column; gap: 1px; }.hex small { font-size: 0.6875rem; letter-spacing: 0.02em; opacity: 0.72; }.hex b { font-family: ui-monospace, "SF Mono", Menlo, monospace; font-size: 0.875rem; font-weight: 600; letter-spacing: 0.03em; }.bottombar { display: flex; justify-content: flex-end; }.cta { background: var(--cta); border: 0px; border-radius: 9px; color: var(--cta-ink); cursor: pointer; font-family: inherit; font-size: 0.8125rem; font-weight: 600; padding: 9px 18px; }.modal { background: var(--card); border: 1px solid var(--edge); border-radius: 14px; box-shadow: rgba(0, 0, 0, 0.35) 0px 18px 50px; color: var(--ink); max-width: min(440px, -48px + 100vw); padding: 18px; width: 100%; }.modal::backdrop { background: rgba(10, 12, 14, 0.45); }.modal-head { align-items: center; display: flex; justify-content: space-between; margin-bottom: 12px; }.modal-head h2 { font-size: 0.9375rem; font-weight: 650; margin: 0px; }.ghost { align-items: center; background: none; border: 0px; border-radius: 9px; color: var(--muted); cursor: pointer; display: inline-flex; font-family: inherit; font-size: 0.875rem; height: 28px; justify-content: center; line-height: 1; padding: 0px; width: 28px; }.ghost:hover { background: var(--pill); color: var(--ink); }.tabs { background: var(--pill); border-radius: 9px; display: flex; gap: 2px; margin-bottom: 12px; padding: 3px; }.tab { background: none; border: 0px; border-radius: 7px; color: var(--muted); cursor: pointer; flex: 1 1 0%; font-family: inherit; font-size: 0.75rem; font-weight: 550; padding: 6px 10px; }.tab[aria-selected="true"] { background: var(--card); box-shadow: rgba(0, 0, 0, 0.12) 0px 1px 2px; color: var(--ink); }.code { background: var(--code); border: 1px solid var(--edge); border-radius: 9px; font-family: ui-monospace, "SF Mono", Menlo, monospace; font-size: 0.75rem; line-height: 1.7; margin: 0px 0px 12px; max-height: 220px; overflow: auto; padding: 12px 14px; }.modal-foot { align-items: center; display: flex; gap: 8px; justify-content: flex-end; }#export-copy { justify-content: center; min-width: 84px; }#export-download { min-width: 133px; }
